INSERT INTO public.lcia_gwp_vintage VALUES
	('CML 2001', 'Electricity grid intensity (eGRID US, Ember Global/EU)', 'as published by the source', 'CO2e intensities taken as published (eGRID 2023 US 0.350, Ember 2024 Global 0.473, Ember EU-27 2023 0.242 kg/kWh); not recomputed from CH4/N2O here, so they carry the source''s own GWP set.', NULL, 'migrate-029', '2026-10-22 03:29:11+00'),
	('CML 2001', 'EPA GHG Hub fuel combustion CO2e (Coal, Wood, Fuel Oil, LPG; migrate-012/028)', 'IPCC AR5', 'CO2 + CH4 x 28 + N2O x 265 per MMBtu (migrate-012 header; scripts/sync-epa-factors.mjs GWP100). Live: Coal 94.012, Fuel Oil 74.203, LPG 61.953, Wood 94.956 kg CO2 eq/MMBtu. Wood check: 93.8 + 0.0072 x 28 + 0.0036 x 265 = 94.956.', NULL, 'migrate-029', '2026-10-22 03:29:11+00'),
	('CML 2001', 'GHG characterization (CH4, N2O)', 'IPCC AR5', 'CH4 28 (migrate-009 2a, IPCC AR5), N2O 265 (openLCA CML 2001 seed).', NULL, 'migrate-029', '2026-10-22 03:29:11+00'),
	('CML 2001', 'Natural Gas combustion, per m3 (migrate-009 2d / 019)', 'CO2 only', 'EPA GHG Emission Factors Hub: 53.06 kg CO2/MMBtu / 28.263 m3/MMBtu = 1.877 kg CO2/m3. CH4 and N2O are not included (with them at AR5: 53.11 kg CO2e/MMBtu). The 28.263 m3/MMBtu basis is about 1,002 Btu/scf; see CALCULATIONS.md data-quality note E7.', NULL, 'migrate-029', '2026-10-22 03:29:11+00'),
	('CML 2001', 'Refrigerant R-410A (50/50 HFC-32/HFC-125 blend)', 'IPCC AR4', 'R-410A 2088 kg CO2 eq/kg. AR4 0.5 x 675 + 0.5 x 3500 = 2087.5; AR5 0.5 x 677 + 0.5 x 3170 = 1923.5. migrate-009 2f only replaces values outside 1000-2500, so 2088 was kept.', 'AR4 refrigerant value inside a method whose CH4/N2O are AR5 (or mixed). Decide whether to set 1924 (AR5).', 'migrate-029', '2026-10-22 03:29:11+00'),
	('ReCiPe Midpoint (H)', 'Electricity grid intensity (eGRID US, Ember Global/EU)', 'as published by the source', 'CO2e intensities taken as published (eGRID 2023 US 0.350, Ember 2024 Global 0.473, Ember EU-27 2023 0.242 kg/kWh); not recomputed from CH4/N2O here, so they carry the source''s own GWP set.', NULL, 'migrate-029', '2026-10-22 03:29:11+00'),
	('ReCiPe Midpoint (H)', 'EPA GHG Hub fuel combustion CO2e (Coal, Wood, Fuel Oil, LPG; migrate-012/028)', 'IPCC AR5', 'CO2 + CH4 x 28 + N2O x 265 per MMBtu (migrate-012 header; scripts/sync-epa-factors.mjs GWP100). Live: Coal 94.012, Fuel Oil 74.203, LPG 61.953, Wood 94.956 kg CO2 eq/MMBtu. Wood check: 93.8 + 0.0072 x 28 + 0.0036 x 265 = 94.956.', NULL, 'migrate-029', '2026-10-22 03:29:11+00'),
	('ReCiPe Midpoint (H)', 'GHG characterization (CH4, N2O)', 'mixed: CH4 AR5 (28, migrate-009 2a) with N2O 298 (AR4 / ReCiPe 2016 H)', 'CH4 28 (migrate-009 2a), N2O 298 (openLCA ReCiPe Midpoint (H) seed). ReCiPe 2008 H = AR4 (25/298); ReCiPe 2016 H = CH4 34 non-fossil / 36 fossil, N2O 298.', 'CH4 28 (AR5) sits beside N2O 298 (not AR5 265). Decide which ReCiPe version and GWP set this method row represents and align CH4/N2O to it.', 'migrate-029', '2026-10-22 03:29:11+00'),
	('ReCiPe Midpoint (H)', 'Natural Gas combustion, per m3 (migrate-009 2d / 019)', 'CO2 only', 'EPA GHG Emission Factors Hub: 53.06 kg CO2/MMBtu / 28.263 m3/MMBtu = 1.877 kg CO2/m3. CH4 and N2O are not included (with them at AR5: 53.11 kg CO2e/MMBtu). The 28.263 m3/MMBtu basis is about 1,002 Btu/scf; see CALCULATIONS.md data-quality note E7.', NULL, 'migrate-029', '2026-10-22 03:29:11+00'),
	('ReCiPe Midpoint (H)', 'Refrigerant R-410A (50/50 HFC-32/HFC-125 blend)', 'IPCC AR4', 'R-410A 2088 kg CO2 eq/kg. AR4 0.5 x 675 + 0.5 x 3500 = 2087.5; AR5 0.5 x 677 + 0.5 x 3170 = 1923.5. migrate-009 2f only replaces values outside 1000-2500, so 2088 was kept.', 'AR4 refrigerant value inside a method whose CH4/N2O are AR5 (or mixed). Decide whether to set 1924 (AR5).', 'migrate-029', '2026-10-22 03:29:11+00'),
	('TRACI 2.1', 'Electricity grid intensity (eGRID US, Ember Global/EU)', 'as published by the source', 'CO2e intensities taken as published (eGRID 2023 US 0.350, Ember 2024 Global 0.473, Ember EU-27 2023 0.242 kg/kWh); not recomputed from CH4/N2O here, so they carry the source''s own GWP set.', NULL, 'migrate-029', '2026-10-22 03:29:11+00'),
	('TRACI 2.1', 'EPA GHG Hub fuel combustion CO2e (Coal, Wood, Fuel Oil, LPG; migrate-012/028)', 'IPCC AR5', 'CO2 + CH4 x 28 + N2O x 265 per MMBtu (migrate-012 header; scripts/sync-epa-factors.mjs GWP100). Live: Coal 94.012, Fuel Oil 74.203, LPG 61.953, Wood 94.956 kg CO2 eq/MMBtu. Wood check: 93.8 + 0.0072 x 28 + 0.0036 x 265 = 94.956.', 'See the TRACI 2.1 lciafmt row: these are AR5 inside an otherwise AR4 method.', 'migrate-029', '2026-10-22 03:29:11+00'),
	('TRACI 2.1', 'lciafmt GHG characterization (CH4, N2O, SF6, HFCs; migrate-015)', 'IPCC AR4', 'CH4 25, N2O 298, SF6 22800, HFC-134a 1430 (lciafmt TRACI 2.1, US EPA). AR4 reference: 25 / 298 / 22800 / 1430; AR5: 28 / 265 / 23500 / 1300.', 'TRACI 2.1 mixes GWP sets: these lciafmt rows are AR4 (CH4 25) while the EPA fuel rows filed under TRACI 2.1 embed AR5 (CH4 28, N2O 265). Decide: (a) keep AR4 for consistency with the published TRACI 2.1 method and recompute the 4 fuel rows at AR4 (Coal 94.032, Wood 95.053, Fuel Oil 74.214, LPG 61.964 kg CO2 eq/MMBtu), or (b) move the TRACI GHG rows to AR5 (CH4 28, N2O 265, SF6 23500, HFCs per AR5 Table 8.A.1) and say the method is TRACI 2.1 with AR5 GWPs. Methane direct emissions differ by 12% between the two (25 vs 28).', 'migrate-029', '2026-10-22 03:29:11+00'),
	('TRACI 2.1', 'Natural Gas combustion, per m3 (migrate-009 2d / 019)', 'CO2 only', 'EPA GHG Emission Factors Hub: 53.06 kg CO2/MMBtu / 28.263 m3/MMBtu = 1.877 kg CO2/m3. CH4 and N2O are not included (with them at AR5: 53.11 kg CO2e/MMBtu). The 28.263 m3/MMBtu basis is about 1,002 Btu/scf; see CALCULATIONS.md data-quality note E7.', NULL, 'migrate-029', '2026-10-22 03:29:11+00'),
	('TRACI 2.1', 'Refrigerant R-410A (50/50 HFC-32/HFC-125 blend)', 'IPCC AR4', 'R-410A 2088 kg CO2 eq/kg. AR4 0.5 x 675 + 0.5 x 3500 = 2087.5; AR5 0.5 x 677 + 0.5 x 3170 = 1923.5. migrate-009 2f only replaces values outside 1000-2500, so 2088 was kept.', NULL, 'migrate-029', '2026-10-22 03:29:11+00');
INSERT INTO public.permissions VALUES
	(1, 'owner', 'Full control over the project including deletion'),
	(2, 'admin', 'Can manage project settings and members'),
	(3, 'editor', 'Can edit project data but cannot manage members'),
	(4, 'viewer', 'Read-only access to project data');
INSERT INTO public.process_templates VALUES
	(1, 'Laser cutting', 'cutting', 'min', 'Minutes of cutting time at the machine', 'Cutting sheet or tube with a laser. Energy follows the cutting head and the chiller; the assist gas is consumed at a rate per minute of cut.', 'LCAPIX process checklist. Amounts are entered from the machine in front of you: nameplate power for electricity, gas supplier data for assist gas.', 0, NULL, '2026-10-22 03:29:10+00'),
	(2, 'CNC machining', 'cutting', 'min', 'Minutes of spindle time', 'Milling or turning. The spindle rarely runs at nameplate power; use the load factor from the machine or the equipment list.', 'LCAPIX process checklist. Amounts entered by the user.', 0, NULL, '2026-10-22 03:29:10+00'),
	(3, 'MIG / TIG welding', 'joining', 'min', 'Minutes of arc-on time', 'Arc-on minutes drive both the power draw and the shielding gas. Setup and idle time are not arc-on time.', 'LCAPIX process checklist. Amounts entered by the user.', 0, NULL, '2026-10-22 03:29:10+00'),
	(4, 'Powder coating', 'finishing', 'm2', 'Square metres of coated surface', 'Spray plus cure. The powder is consumed per square metre at the transfer efficiency of the booth; the oven draws power per batch, so divide the batch by the area it holds.', 'LCAPIX process checklist. Amounts entered by the user.', 0, NULL, '2026-10-22 03:29:10+00'),
	(5, 'Heat treatment / curing oven', 'heat', 'h', 'Hours the oven runs', 'An oven is a batch process: work out the energy per hour, then divide by the number of parts in a batch to get the amount per unit.', 'LCAPIX process checklist. Amounts entered by the user.', 0, NULL, '2026-10-22 03:29:10+00'),
	(6, 'Injection moulding', 'forming', 'kg', 'Kilograms of polymer shot', 'Energy per kilogram of polymer processed, plus the regrind or scrap rate of the tool.', 'LCAPIX process checklist. Amounts entered by the user.', 0, NULL, '2026-10-22 03:29:10+00'),
	(7, 'Sheet forming / press', 'forming', 'unit', 'Parts pressed', 'Press energy per stroke and the lubricant used per part.', 'LCAPIX process checklist. Amounts entered by the user.', 0, NULL, '2026-10-22 03:29:10+00'),
	(8, 'Washing / degreasing', 'finishing', 'unit', 'Parts washed', 'Heated washers draw energy continuously and consume detergent and water per part.', 'LCAPIX process checklist. Amounts entered by the user.', 0, NULL, '2026-10-22 03:29:10+00');
INSERT INTO public.process_template_flows VALUES
	(1, 1, 7, 'Electricity, kWh', 'input', NULL, 'kWh', 'Nameplate kW x minutes / 60 x load. The machine calculator does this for you.', 1),
	(2, 1, 2426, 'Assist gas: nitrogen or oxygen, m3 or kg', 'input', NULL, 'm3', 'Flow rate at the head x cutting minutes. On the gas invoice or the machine settings.', 2),
	(3, 2, 7, 'Electricity, kWh', 'input', NULL, 'kWh', 'Spindle kW x minutes / 60 x load factor. Idle time counts at a lower load.', 1),
	(4, 2, NULL, 'Cutting fluid or coolant, litres', 'input', NULL, 'l', 'Top-up volume per period divided by the machine minutes in that period.', 2),
	(5, 3, 7, 'Electricity, kWh', 'input', NULL, 'kWh', 'Welder kW x arc-on minutes / 60. Duty cycle is not load: arc-on minutes already account for it.', 1),
	(6, 3, 3300, 'Shielding gas: argon or an argon mix, m3', 'input', NULL, 'm3', 'Gas flow rate (l/min) x arc-on minutes / 1000.', 2),
	(7, 3, NULL, 'Filler wire or rod, kg', 'input', NULL, 'kg', 'Spool weight divided by the arc-on minutes it lasts.', 3),
	(8, 4, 7, 'Electricity, kWh', 'input', NULL, 'kWh', 'Booth plus oven. Oven kW x cure hours, divided by the area cured in that batch.', 1),
	(9, 4, NULL, 'Powder coating material, kg', 'input', NULL, 'kg', 'Powder used per m2 at the booth transfer efficiency. Reclaimed overspray does not count twice.', 2),
	(10, 5, 7, 'Electricity, kWh', 'input', NULL, 'kWh', 'Oven kW x hours. Divide by the parts in a batch to get the amount per part.', 1),
	(11, 5, 10, 'Natural gas, m3 or kWh', 'input', NULL, 'm3', 'Only for a gas-fired oven. Meter reading per hour, or burner rating x hours.', 2),
	(12, 6, 7, 'Electricity, kWh', 'input', NULL, 'kWh', 'Machine kWh per kg of polymer processed, from the machine log or a shot-weight estimate.', 1),
	(13, 6, NULL, 'Polymer, kg (the material you mould)', 'input', NULL, 'kg', 'Shot weight x shots, including sprue and runner if they are not reground.', 2),
	(14, 7, 7, 'Electricity, kWh', 'input', NULL, 'kWh', 'Press kW x cycle time / 3600 per part.', 1),
	(15, 7, NULL, 'Forming lubricant, kg or litres', 'input', NULL, 'kg', 'Consumption per period divided by the parts pressed in it.', 2),
	(16, 8, 7, 'Electricity, kWh', 'input', NULL, 'kWh', 'Heater kW x hours running, divided by the parts washed in that time.', 1),
	(17, 8, 8, 'Water, m3 or litres', 'input', NULL, 'l', 'Bath volume divided by the parts washed before it is changed, plus top-up.', 2),
	(18, 8, NULL, 'Detergent or degreaser, kg', 'input', NULL, 'kg', 'Dose per bath divided by the parts washed in it.', 3);
